import sys, random, json
sys.path.insert(0, "/workspace/tests")
from run_sub import run
import refmodel

def canon_name(s):
    if s == '.': return '.'
    return '.'.join(l.lower() for l in s[:-1].split('.')) + '.'

random.seed(31337)
names = ["a.t.","b.t.","c.t.","x.y.t.","t.","*.t.","d.e.t.","q.*.t.","z.t.","sub.t."]
types = ["A","AAAA","TXT","CNAME"]
mismatch = 0
for trial in range(4000):
    # random zones
    nzones = random.randint(1,3)
    origins = ["t.","sub.t.","."] 
    random.shuffle(origins)
    zones = []
    for oi in range(nzones):
        origin = origins[oi]
        recs = []
        for _ in range(random.randint(0,5)):
            owner = random.choice(names)
            ty = random.choice(types)
            if ty == "A": data = "%d.%d.%d.%d" % tuple(random.randint(0,255) for _ in range(4))
            elif ty == "AAAA": data = "2001:db8::%d" % random.randint(0,9)
            elif ty == "TXT": data = "t%d" % random.randint(0,99)
            else: data = random.choice(names)
            recs.append({"owner":owner,"type":ty,"data":data})
        # validate coherence, skip otherwise
        byo = {}
        bad = False
        for r in recs:
            o = canon_name(r['owner'])
            if origin != '.' and not (o == origin or o.endswith('.'+origin)): bad = True
            byo.setdefault(o, {}).setdefault(r['type'], set()).add(r['data'] if r['type']!='CNAME' else canon_name(r['data']))
        for o, ts in byo.items():
            if 'CNAME' in ts:
                if len(ts) > 1 or len(ts['CNAME']) > 1 or o == origin: bad = True
        if bad: continue
        zones.append({"origin":origin,"records":recs})
    profiles = [{"id":"p%d"%i,"max_aliases":random.randint(0,3),
                 "cname":random.choice(["follow","stop"]),
                 "wildcard":random.choice(["rfc","off","one-label"])} for i in range(random.randint(1,4))]
    queries = [{"id":"q%d"%i,"name":random.choice(names),"type":random.choice(types),"cost":1}
               for i in range(random.randint(1,5))]
    doc = {"zones":zones,"profiles":profiles,"queries":queries,"observations":[]}
    out = run(doc)
    if 'error' in out:
        print("unexpected invalid:", json.dumps(doc)); mismatch += 1; break
    # reference
    rz = refmodel.build(zones)
    for q in queries:
        for p in profiles:
            rcode, term, final, ans, tr = refmodel.run(q['name'], q['type'], p, rz)
            got = [r for r in out['runs'] if r['query']==q['id'] and r['profile']==p['id']][0]
            if (rcode, term, final, ans, tr) != (got['rcode'], got['termination'], got['final_name'], got['answer'], got['trace']):
                print("MISMATCH", json.dumps(doc))
                print(" ref", rcode, term, final, ans, tr)
                print(" got", got)
                mismatch += 1
                break
        if mismatch: break
    if mismatch: break
print("cross-check done, mismatches:", mismatch)
